// Shared by the Edge Functions (Deno): one Postgres pool and one EdgeContext per isolate.
// core.js is generated by `node scripts/bundle-edge.mjs` (apps/cloud/src/edge → ESM bundle).
import pg from 'npm:pg@8.16.3';
// @ts-types="./core.d.ts"
import { createPostgresDriver, edgeContext } from './core.js';
import type { EdgeContext } from './core.d.ts';

// BIGINT (int8) and NUMERIC come back as strings by default; the cloud keeps everything in Number range
// (same as apps/cloud/src/db/open.ts).
pg.types.setTypeParser(20, Number);
pg.types.setTypeParser(1700, Number);

/** TLS to the database: off for a local stack (supabase start), on otherwise; TS_DB_SSL=disable|require overrides. */
function sslFor(url: string): false | { rejectUnauthorized: boolean } {
  const mode = Deno.env.get('TS_DB_SSL');
  if (mode === 'disable') return false;
  if (mode === 'require') return { rejectUnauthorized: false };
  if (/sslmode=disable/.test(url)) return false;
  const host = (() => {
    try {
      return new URL(url).hostname;
    } catch {
      return '';
    }
  })();
  const local = host === 'localhost' || host === '127.0.0.1' || host === 'host.docker.internal' || host.startsWith('supabase_db') || host === 'db';
  return local ? false : { rejectUnauthorized: false };
}

let ctx: EdgeContext | null = null;

export function context(): EdgeContext {
  if (ctx) return ctx;
  const url = Deno.env.get('SUPABASE_DB_URL');
  if (!url) throw new Error('SUPABASE_DB_URL is not set');
  const pool = new pg.Pool({ connectionString: url, ssl: sslFor(url), max: 3, idleTimeoutMillis: 10_000 });
  pool.on('error', (e: Error) => console.error(`Postgres pool: ${e.message}`));
  ctx = edgeContext(createPostgresDriver(pool), Deno.env.toObject());
  return ctx;
}

/** Wraps a handler: a broken configuration answers JSON 500 instead of a bare crash. */
export function serve(handler: (req: Request, ctx: EdgeContext) => Promise<Response>): void {
  Deno.serve(async (req: Request) => {
    let c: EdgeContext;
    try {
      c = context();
    } catch (e) {
      console.error(e);
      return new Response(JSON.stringify({ error: { code: 'INTERNAL', message: 'Облако не настроено' } }), {
        status: 500,
        headers: { 'content-type': 'application/json; charset=utf-8' },
      });
    }
    return handler(req, c);
  });
}
